function breakEven(c) {
  const saving = c.manualPerRun - c.autoPerRun - c.maintenancePerRun;
  if (saving <= 0) return null;
  return Math.max(1, Math.ceil(c.buildCost / saving));
}

function roi(c, runs) {
  const manual = c.manualPerRun * runs;
  const auto = c.buildCost + (c.autoPerRun + c.maintenancePerRun) * runs;
  return Math.round(((manual - auto) / auto) * 100 * 10) / 10;
}
